import { writeFile } from "node:fs/promises";
import type { Command } from "commander";
import { apiClient } from "../../api.js";

function toCsv(rows: { id: string; name: string; email: string; createdAt: string }[]) {
  const header = "id,name,email,created_at";
  const esc = (v: string) => (/[",\n]/.test(v) ? `"${v.replaceAll('"', '""')}"` : v);
  return [header, ...rows.map((r) => [r.id, r.name, r.email, r.createdAt].map(esc).join(","))].join("\n");
}

export function registerClientsExport(clients: Command) {
  clients
    .command("export")
    .description("Export all clients to a CSV file")
    .requiredOption("--out <file>", "output path")
    .action(async (opts: { out: string }) => {
      const api = await apiClient();
      const rows = await api.clients.listAll();
      await writeFile(opts.out, toCsv(rows) + "\n");
      process.stdout.write(`exported ${rows.length} clients to ${opts.out}\n`);
    });
}

