import { ledger } from "../ledger.js";
import { logger } from "../logger.js";

export async function billingSync(job: Job<{ orgId: string; since: string }>) {
  const { orgId, since } = job.data;
  for await (const invoice of stripe.invoices.list({ created: { gte: Date.parse(since) / 1000 }, expand: ["data.charge.refunds"] })) {
    await ledger.upsertInvoice(orgId, invoice);
    const refunds = invoice.charge && typeof invoice.charge !== "string" ? invoice.charge.refunds?.data ?? [] : [];
    for (const refund of refunds) {
      await ledger.insertRefund(orgId, { stripeRefundId: refund.id, amount: refund.amount, invoiceId: invoice.id });
    }
  }
  logger.info({ jobId: job.id, orgId }, "billing sync done");
}

