import type { FastifyPluginAsyncZod } from "fastify-type-provider-zod";
import { z } from "zod";
import { getInvoice, markSent } from "../../../services/invoices.js";

export const sendInvoice: FastifyPluginAsyncZod = async (app) => {
  app.post("/invoices/:id/send", { schema: { params: z.object({ id: z.string().uuid() }) } }, async (req, reply) => {
    const invoice = await getInvoice(app.db, req.auth.orgId, req.params.id);
    if (!invoice) return reply.notFound();
    await app.queues.email.add("invoice-sent", { invoiceId: invoice.id }, { jobId: `invoice-sent:${invoice.id}` });
    await markSent(app.db, invoice.id);
    return reply.code(202).send({ status: "queued" });
  });
};

