import type { FastifyPluginAsyncZod } from "fastify-type-provider-zod";
import { z } from "zod";
import { getInvoice } from "../../../services/invoices.js";

export const remindInvoice: FastifyPluginAsyncZod = async (app) => {
  app.post("/invoices/:id/remind", { schema: { params: z.object({ id: z.string().uuid() }) } }, async (req, reply) => {
    const invoice = await getInvoice(app.db, req.auth.orgId, req.params.id, { with: { client: true } });
    if (!invoice) return reply.notFound();
    if (!invoice.client.crmWebhookUrl) return reply.code(204).send();
    const res = await fetch(invoice.client.crmWebhookUrl, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ event: "invoice.reminder", invoiceId: invoice.id, number: invoice.number, dueAt: invoice.dueAt }),
    });
    return reply.code(res.ok ? 202 : 502).send({ delivered: res.ok });
  });
};

